async function run(input, tools) {
  const settings = input?.settings || {};
  const sheet = settings.sheet_tab;

  let rows = [];
  try {
    const res = await tools.sheets.read({ sheet });
    rows = Array.isArray(res?.rows) ? res.rows : [];
  } catch (e) {
    rows = [];
  }

  const column_totals = {};
  for (const row of rows) {
    if (!row || typeof row !== "object") continue;
    for (const key of Object.keys(row)) {
      const v = row[key];
      if (typeof v === "number" && isFinite(v)) {
        column_totals[key] = (column_totals[key] || 0) + v;
      }
    }
  }
  const row_count = rows.length;

  let yesterday = input?.memory?.yesterday;
  if (yesterday === undefined || yesterday === null) {
    try {
      const m = await tools.memory.get({ key: "yesterday" });
      yesterday = m?.value;
    } catch (e) {
      yesterday = null;
    }
  }

  const hasYesterday = yesterday && typeof yesterday === "object";
  const prevRowCount = hasYesterday && typeof yesterday.row_count === "number" ? yesterday.row_count : null;
  const prevTotals = hasYesterday && yesterday.column_totals && typeof yesterday.column_totals === "object"
    ? yesterday.column_totals : null;

  const new_rows = prevRowCount === null ? 0 : row_count - prevRowCount;

  const column_changes = {};
  for (const key of Object.keys(column_totals)) {
    const prev = prevTotals && typeof prevTotals[key] === "number" ? prevTotals[key] : 0;
    column_changes[key] = column_totals[key] - prev;
  }

  const lines = [];
  if (!hasYesterday || prevRowCount === null) {
    lines.push("First run: no yesterday data to compare.");
    lines.push(`Rows: ${row_count}`);
    for (const key of Object.keys(column_totals)) {
      lines.push(`${key}: ${column_totals[key]}`);
    }
  } else {
    lines.push(`Rows: ${row_count} (${new_rows >= 0 ? "+" : ""}${new_rows})`);
    for (const key of Object.keys(column_changes)) {
      const c = column_changes[key];
      lines.push(`${key}: ${column_totals[key]} (${c >= 0 ? "+" : ""}${c})`);
    }
  }

  return {
    row_count,
    column_totals,
    new_rows,
    column_changes,
    summary_text: lines.join("\n"),
  };
}

