async function run(input, tools) {
  const rows = Number.isFinite(Number(input.row_count)) ? Number(input.row_count) : 0;
  const totals = {};
  const raw = input.column_totals;
  if (raw && typeof raw === "object" && !Array.isArray(raw)) {
    for (const [k, v] of Object.entries(raw)) {
      totals[k] = Number.isFinite(Number(v)) ? Number(v) : 0;
    }
  }
  await tools.memory.set({ key: "yesterday", value: { rows, totals } });
  return {};
}
